import fs from 'node:fs/promises'
import http from 'node:http'
import https from 'node:https'
import path from 'node:path'
import { once } from 'node:events'
import { pathToFileURL } from 'node:url'
import { createRequire } from 'node:module'

const root = process.cwd()
const backend = path.join(root, 'backend')
const frontend = path.join(root, 'frontend')
const load = p => import(pathToFileURL(path.join(backend, p)))
const require = createRequire(path.join(backend, 'package.json'))
const express = require('express')
const sharp = require('sharp')
const jwt = require('jsonwebtoken')
const { createImageStorage } = await load('src/services/imageStorage.js')
const { createUploadRouter } = await load('src/routes/upload.js')
const { default: User } = await load('src/models/User.js')

process.env.ADMIN_EMAILS = 'owner@example.test'
process.env.JWT_SECRET = 'disposable-browser-fixture-only'
// Explicit model-method fixture, never connect to MongoDB or load .env.
User.findById = async () => ({ _id: 'actor', email: 'owner@example.test' })
const objects = new Map()
const events = []
let properties = []
let posts = []
let storage
const app = express()
const server = https.createServer({ key: await fs.readFile(path.join(root, 'fixture-key.pem')), cert: await fs.readFile(path.join(root, 'fixture-cert.pem')) }, app)
server.listen(Number(process.env.FIXTURE_PORT ?? 0), '127.0.0.1')
await once(server, 'listening')
const origin = `https://127.0.0.1:${server.address().port}`
const mediaBase = `${origin}/media`
const env = { R2_ACCOUNT_ID: 'a'.repeat(32), R2_ACCESS_KEY_ID: 'fixture-access', R2_SECRET_ACCESS_KEY: 'fixture-secret', R2_BUCKET_NAME: 'fixture-images', R2_PUBLIC_URL: mediaBase }
const client = { async send(command) {
  const { Key, Body, ContentType, CacheControl } = command.input
  if (command.constructor.name === 'PutObjectCommand') objects.set(Key, { body: Body, type: ContentType, cache: CacheControl })
  else if (command.constructor.name === 'DeleteObjectCommand') objects.delete(Key)
  else throw new Error('Unexpected fixture storage command')
  return {}
} }
storage = createImageStorage({ env, client })
const input = await sharp({ create: { width: 1800, height: 1200, channels: 4, background: '#178963' } }).png().toBuffer()
await fs.writeFile(path.join(root, 'fixture-input.png'), input)
const initial = await storage.uploadImages([{ buffer: input }, { buffer: input }])
properties = [{ _id: '64b000000000000000000001', title: 'R2 fixture home', description: 'Disposable browser media verification fixture; not real inventory.', location: 'Nairobi', type: 'Apartment', listingPurpose: 'rent', availability: 'available', price: 50000, offerPercent: 10, effectivePrice: 45000, bedrooms: 2, bathrooms: 2, area: 800, features: ['Balcony'], featured: true, images: initial.urls }]
posts = [{ _id: '64b000000000000000000002', title: 'R2 fixture article', content: 'Disposable browser fixture article.', image: initial.urls[0], author: 'Fixture', category: 'Market', date: '2026-11-26', readTime: '2 min read', featured: true }]
const token = jwt.sign({ userId: 'actor' }, process.env.JWT_SECRET)
app.use((req, res, next) => {
  const requestPath = req.path
  res.on('finish', () => events.push({ method: req.method, path: requestPath, status: res.statusCode }))
  next()
})
app.get('/media/*', (req, res) => {
  // Match a direct R2 custom domain: the entire public path is the object key.
  const object = objects.get(req.path.slice(1))
  if (!object) return res.sendStatus(404)
  res.set({ 'Content-Type': object.type, 'Cache-Control': object.cache }).send(object.body)
})
app.get('/fixture/bootstrap', (_req, res) => res.json({ token }))
app.get('/fixture/events', (_req, res) => res.json({ events, objectCount: objects.size, images: properties[0].images }))
app.use('/api/upload', createUploadRouter({ storeImages: files => storage.uploadImages(files) }))
app.use(express.json())
app.get('/api/auth/profile', (_req, res) => res.json({ id: 'actor', name: 'Fixture Owner', email: 'owner@example.test', isAdmin: true }))
app.get('/api/properties', (_req, res) => res.json(properties))
app.get('/api/properties/:id', (req, res) => {
  const property = properties.find(p => p._id === req.params.id)
  return property ? res.json(property) : res.sendStatus(404)
})
app.put('/api/properties/:id', (req, res) => {
  const i = properties.findIndex(p => p._id === req.params.id)
  if (i < 0) return res.sendStatus(404)
  properties[i] = { ...properties[i], ...req.body }
  res.json(properties[i])
})
app.get('/api/features', (_req, res) => res.json([{ _id: '64b000000000000000000003', name: 'Balcony' }]))
app.get('/api/blog', (_req, res) => res.json(posts))
app.get('/api/blog/:id', (req, res) => res.json(posts.find(p => p._id === req.params.id)))
app.get('/api/admin/stats', (_req, res) => res.json({ totals: { properties: 1, activeListings: 1, blogPosts: 1, inquiries: 0 }, monthOverMonth: { properties: 0, activeListings: 0, blogPosts: 0, inquiries: 0 } }))
app.get('/api/admin/recent-activity', (_req, res) => res.json([]))
app.use('/api', (_req, res) => res.status(404).json({ message: 'Unknown fixture API' }))
app.use(express.static(path.join(frontend, 'dist')))
app.get('*', (_req, res) => res.sendFile(path.join(frontend, 'dist/index.html')))
await fs.writeFile(path.join(root, 'runtime.json'), JSON.stringify({ origin, mediaBase, propertyId: properties[0]._id, postId: posts[0]._id }))
console.log('Owned HTTPS browser fixture ready')
let stopping = false
async function cleanup() {
  if (stopping) return
  stopping = true
  objects.clear()
  await new Promise(resolve => { server.close(resolve); server.closeAllConnections() })
  await fs.writeFile(path.join(root, 'cleanup.json'), JSON.stringify({ objectCount: objects.size, serverClosed: !server.listening }))
}
for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, () => cleanup().then(() => process.exit(0)))
